import{_ as e,o as t,c as i,aw as r}from"./chunks/framework.DLufY-ao.js";const m=JSON.parse('{"title":"YAGNI","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/theory/refactoring/best-practices/yagni.md","filePath":"wiki/dev-commit/theory/refactoring/best-practices/yagni.md"}'),o={name:"wiki/dev-commit/theory/refactoring/best-practices/yagni.md"};function l(n,a,c,s,d,_){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="yagni" tabindex="-1">YAGNI <a class="header-anchor" href="#yagni" aria-label="Permalink to &quot;YAGNI&quot;">​</a></h1><h2 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Определение</p><ul><li><strong>YAGNI</strong> («You aren&#39;t gonna need it». «Вам это не понадобится») - процесс и принцип проектирования ПО, при котором в качестве основной цели и/или ценности декларируется отказ от избыточной функциональности, то есть отказ добавления функциональности, в которой нет непосредственной надобности</li></ul></div><h3 id="последствия-написание-кода-которыи-не-нужно-прямо-сеичас" tabindex="-1">Последствия написание кода, который не нужно прямо сейчас <a class="header-anchor" href="#последствия-написание-кода-которыи-не-нужно-прямо-сеичас" aria-label="Permalink to &quot;Последствия написание кода, который не нужно прямо сейчас&quot;">​</a></h3><ul><li>Тратится время на добавление, тестирование и улучшение необходимой функциональности</li><li>Новые функции должны быть отлажены, документированы и сопровождаться</li><li>Новая функциональность ограничивает то, что может быть сделано в будущем, - ненужные новые функции могут впоследствии помешать добавить новые нужные</li><li>Пока новые функции действительно не нужны, трудно полностью предугадать, что они должны делать, и протестировать их. Если новые функции тщательно не протестированы, они могут неправильно работать, когда впоследствии понадобятся</li><li>Это приводит к тому, что программное обеспечение становится более сложным</li></ul>',5)])])}const u=e(o,[["render",l]]);export{m as __pageData,u as default};
